-- Fixed asset register 2026-27: import into the asset software. Generated by generate-far-import.py; safe to read.
-- 505 register rows, purchase value 194,058,695.61. Sends NO notifications. Refuses to run twice.
-- Existing IT assets with the same serial (or same bill and cost) are not duplicated: blank finance
-- fields are filled in. Depreciation continues from the register: 2025-26 is stored as the 2025 schedule.
\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM audit_events WHERE action = 'FAR_IMPORTED' AND changes->>'tag' = '2026-27') THEN
    RAISE EXCEPTION 'The fixed asset register 2026-27 was already imported.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM depreciation_method_rules WHERE method_code = 'NO_DEPRECIATION') THEN
    RAISE EXCEPTION 'Deploy the latest version first (migration 063_depreciation_none.sql is missing).';
  END IF;
END $$;
CREATE TEMP TABLE importer ON COMMIT DROP AS
  SELECT ur.user_id AS id FROM user_roles ur WHERE ur.role_code='SUPER_ADMIN' ORDER BY ur.granted_at LIMIT 1;
CREATE TEMP TABLE team_ids ON COMMIT DROP AS SELECT code, id FROM teams WHERE code IN ('IT','ADM','PRJ');

