DO $$ DECLARE s record; BEGIN
  FOR s IN SELECT * FROM (VALUES
    (0, 'IAC-HO', 'Head Office (HO)', 'SITE', NULL),
    (1, 'IAC-HO-GF', 'Ground Floor', 'FLOOR', 'IAC-HO'),
    (2, 'IAC-HO-2F', '2nd Floor', 'FLOOR', 'IAC-HO'),
    (3, 'IAC-HO-3F', '3rd Floor', 'FLOOR', 'IAC-HO'),
    (4, 'IAC-SITE', 'Project Site', 'SITE', NULL),
    (5, 'IAC-SITE-OFFICE', 'Site Office', 'BUILDING', 'IAC-SITE'),
    (6, 'IAC-SITE-TA', 'Training Academy', 'BUILDING', 'IAC-SITE'),
    (7, 'IAC-SITE-SB', 'Security Block & Guard House', 'BUILDING', 'IAC-SITE'),
    (8, 'IAC-SITE-CANTEEN', 'Canteen & Store', 'BUILDING', 'IAC-SITE'),
    (9, 'IAC-SITE-PORTA', 'Porta Cabin', 'BUILDING', 'IAC-SITE'),
    (10, 'IAC-SITE-CC', 'Community Center', 'BUILDING', 'IAC-SITE'),
    (11, 'IAC-AMTALLA', 'Amtalla Guest House', 'SITE', NULL)
  ) v(ord, code, name, level, parent) ORDER BY ord LOOP
    IF NOT EXISTS (SELECT 1 FROM locations WHERE code = s.code) THEN
      INSERT INTO locations(code, site, name, level, parent_id)
      VALUES (s.code, s.name, s.name, s.level, (SELECT id FROM locations WHERE code = s.parent));
    END IF;
  END LOOP;
END $$;
