-- Match IT rows to assets already in the software: a unique serial first, then a unique bill + cost.
CREATE FUNCTION pg_temp.norm(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$ SELECT regexp_replace(lower(coalesce(t,'')), '[^a-z0-9]', '', 'g') $f$;
UPDATE far f SET match_id = m.id, matched_by = 'serial' FROM (
  SELECT f2.ord, min(a.id::text)::uuid AS id, count(DISTINCT a.id) AS n FROM far f2
  JOIN assets a ON a.removed_at IS NULL AND length(pg_temp.norm(a.serial_number)) >= 6
   AND pg_temp.norm(a.serial_number) = ANY (f2.tokens)
  WHERE f2.team = 'IT' GROUP BY f2.ord) m WHERE m.ord = f.ord AND m.n = 1;
UPDATE far f SET match_id = m.id, matched_by = 'bill and cost' FROM (
  SELECT f2.ord, min(a.id::text)::uuid AS id, count(DISTINCT a.id) AS n FROM far f2
  JOIN assets a ON a.removed_at IS NULL AND length(pg_temp.norm(f2.bill)) >= 5
   AND pg_temp.norm(a.invoice_number) = pg_temp.norm(f2.bill) AND abs(a.purchase_cost - f2.cost) <= 1
  WHERE f2.team = 'IT' AND f2.match_id IS NULL GROUP BY f2.ord) m WHERE m.ord = f.ord AND m.n = 1;
-- One register row per existing asset: if two rows point at the same asset, neither is matched.
UPDATE far f SET match_id = NULL, matched_by = NULL WHERE match_id IN (
  SELECT match_id FROM far WHERE match_id IS NOT NULL GROUP BY match_id HAVING count(*) > 1);
UPDATE far f SET cost_agrees = (a.purchase_cost IS NULL OR abs(a.purchase_cost - f.cost) <= 1)
  FROM assets a WHERE a.id = f.match_id;

-- Matched: fill blank finance fields only; take the register depreciation when the cost agrees.
UPDATE assets a SET
  purchase_cost = coalesce(a.purchase_cost, f.cost),
  purchase_date = coalesce(a.purchase_date, f.dop),
  capitalisation_date = coalesce(a.capitalisation_date, f.docap),
  invoice_number = coalesce(nullif(btrim(a.invoice_number), ''), f.bill),
  supplier = coalesce(nullif(btrim(a.supplier), ''), f.party),
  residual_value = CASE WHEN a.residual_value IS NULL AND f.scrap <= coalesce(a.purchase_cost, f.cost) THEN f.scrap ELSE a.residual_value END,
  useful_life_years = coalesce(a.useful_life_years, f.life),
  depreciation_method = CASE WHEN f.cost_agrees THEN f.method ELSE a.depreciation_method END,
  legacy_metadata = coalesce(a.legacy_metadata, '{}'::jsonb) || jsonb_build_object('fixedAssetRegister', f.meta),
  version = a.version + 1, updated_at = now()
FROM far f WHERE f.match_id = a.id;
INSERT INTO audit_events(actor_id, actor_kind, entity_type, entity_id, action, changes, request_id)
SELECT (SELECT id FROM importer), 'USER', 'asset', f.match_id, 'ASSET_UPDATED',
       jsonb_build_object('source', 'Fixed asset register 2026-27', 'row', f.ord, 'matchedBy', f.matched_by,
                          'note', 'Blank finance fields filled from the fixed asset register'), gen_random_uuid()
  FROM far f WHERE f.match_id IS NOT NULL;

-- New assets, numbered from each team's counter.
SELECT pg_advisory_xact_lock(hashtextextended('iac-asset-sequence', 0));
DO $$ DECLARE f record; nxt bigint; prefix text; code text; tid uuid; aid uuid; BEGIN
  FOR f IN SELECT * FROM far WHERE match_id IS NULL ORDER BY ord LOOP
    SELECT id INTO tid FROM team_ids WHERE team_ids.code = f.team;
    SELECT k.next_value, t.asset_code_prefix INTO nxt, prefix FROM team_asset_counters k JOIN teams t ON t.id = k.team_id
     WHERE k.team_id = tid FOR UPDATE OF k;
    LOOP code := 'IAC-' || prefix || '-' || lpad(nxt::text, 6, '0');
      EXIT WHEN NOT EXISTS (SELECT 1 FROM assets WHERE asset_code = code); nxt := nxt + 1; END LOOP;
    UPDATE team_asset_counters SET next_value = nxt + 1 WHERE team_id = tid;
    INSERT INTO assets(asset_code, category, asset_type, description, model, serial_number, ownership_type, status,
      condition, risk_level, owning_team_id, location_id, purchase_date, capitalisation_date, purchase_cost, currency,
      residual_value, depreciation_method, useful_life_years, finance_pending, finance_status, invoice_number, supplier,
      remarks, legacy_metadata, created_by)
    VALUES (code, f.category, f.asset_type, f.description, f.model, f.serial, 'Owned', 'Active', 'Unknown', 'Low', tid,
      (SELECT id FROM locations WHERE locations.code = f.location_code), f.dop, f.docap, f.cost, 'INR', f.scrap, f.method,
      f.life, false, 'APPROVED', f.bill, f.party, f.remarks, jsonb_build_object('fixedAssetRegister', f.meta),
      (SELECT id FROM importer))
    RETURNING id INTO aid;
    UPDATE far SET new_id = aid WHERE ord = f.ord;
    INSERT INTO audit_events(actor_id, actor_kind, entity_type, entity_id, action, changes, request_id)
    VALUES ((SELECT id FROM importer), 'USER', 'asset', aid, 'ASSET_CREATED',
      jsonb_build_object('source', 'Fixed asset register 2026-27', 'row', f.ord, 'assetCode', code), gen_random_uuid());
  END LOOP;
END $$;

-- 2025-26 from the register, so the 2026-27 run continues from the WDV at 31-3-2026.
INSERT INTO depreciation_schedules(asset_id, financial_year_start, method, rate, purchase_cost, opening_value,
  depreciation_charge, closing_value, accumulated_depreciation)
SELECT coalesce(f.new_id, f.match_id), 2025, 'WDV', f.s_rate, f.cost, f.s_opening, f.s_charge, f.s_closing, f.s_accumulated
  FROM far f WHERE f.s_rate IS NOT NULL AND (f.new_id IS NOT NULL OR f.cost_agrees)
ON CONFLICT (asset_id, financial_year_start) DO UPDATE SET method = EXCLUDED.method, rate = EXCLUDED.rate,
  purchase_cost = EXCLUDED.purchase_cost, opening_value = EXCLUDED.opening_value,
  depreciation_charge = EXCLUDED.depreciation_charge, closing_value = EXCLUDED.closing_value,
  accumulated_depreciation = EXCLUDED.accumulated_depreciation;

INSERT INTO audit_events(actor_id, actor_kind, entity_type, entity_id, action, changes, request_id)
SELECT (SELECT id FROM importer), 'USER', 'import', NULL, 'FAR_IMPORTED', jsonb_build_object(
  'tag', '2026-27', 'rows', (SELECT count(*) FROM far), 'created', (SELECT count(*) FROM far WHERE new_id IS NOT NULL),
  'matched', (SELECT count(*) FROM far WHERE match_id IS NOT NULL),
  'schedules', (SELECT count(*) FROM far WHERE s_rate IS NOT NULL AND (new_id IS NOT NULL OR cost_agrees))), gen_random_uuid();

DO $$ DECLARE r record; BEGIN
  RAISE NOTICE 'Register rows: %, created: %, matched to existing assets: % (by serial %, by bill and cost %)',
    (SELECT count(*) FROM far), (SELECT count(*) FROM far WHERE new_id IS NOT NULL),
    (SELECT count(*) FROM far WHERE match_id IS NOT NULL), (SELECT count(*) FROM far WHERE matched_by = 'serial'),
    (SELECT count(*) FROM far WHERE matched_by = 'bill and cost');
  RAISE NOTICE 'Purchase value imported: %', (SELECT sum(cost) FROM far);
  FOR r IN SELECT f.ord, a.asset_code, a.purchase_cost, f.cost FROM far f JOIN assets a ON a.id = f.match_id
            WHERE NOT f.cost_agrees ORDER BY f.ord LOOP
    RAISE NOTICE 'Row %: % already has cost % (register %); kept its own depreciation', r.ord, r.asset_code, r.purchase_cost, r.cost;
  END LOOP;
  FOR r IN SELECT f.ord, a.asset_code, a.status FROM far f JOIN assets a ON a.id = f.match_id
            WHERE a.status IN ('Disposed', 'Sold', 'Retired', 'Scrapped') ORDER BY f.ord LOOP
    RAISE NOTICE 'Row %: % is % in the software but still on the register; it will not be depreciated', r.ord, r.asset_code, r.status;
  END LOOP;
END $$;
COMMIT;
